  "python": {
    "ce": "# A box and a brace — exported by Manim Formula Editor for ManimCE 0.22.\n# Render at 1920×1080, 60 fps:\n#     manim -r 1920,1080 --fps 60 ABoxAndABrace.py ABoxAndABrace\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 540 frames, like the editor's video export.\nfrom manim import *\n\n\nclass ABoxAndABrace(Scene):\n    def construct(self):\n        self.camera.background_color = \"#000000\"\n\n        # sum: 1+2+3+4+5+6\n        sum = MathTex(r\"1+2+3+4+5+6\", font_size=60)\n        sum.move_to([0, 0.6, 0])\n\n        # frame: box, built on sum where its clip starts\n\n        # under: brace, built on frame where its clip starts\n\n        # 0 s – 1.5 s: sum write\n        self.play(Write(sum), run_time=1.5)\n        # 1.5 s – 2 s\n        self.wait(0.5)\n        frame = SurroundingRectangle(sum[0][:5], buff=0.15, color=\"#FFFF00\", corner_radius=0.12).set_fill(\"#FFFF00\")\n        frame.set_z_index(1)\n        # 2 s – 2.6 s: frame create\n        self.play(Create(frame), run_time=0.6)\n        # 2.6 s – 3.5 s\n        self.wait(0.9)\n        frame_to = SurroundingRectangle(sum[0][6:], buff=0.15, color=\"#83C167\", corner_radius=0.12, stroke_width=6, fill_opacity=0.25).set_fill(\"#FFFF00\")\n        # 3.5 s – 4.5 s: frame tween\n        self.play(Transform(frame, frame_to), run_time=1)\n        # 4.5 s – 5.5 s\n        self.wait(1)\n        frame_to_2 = SurroundingRectangle(sum, buff=0.15, color=\"#FFFFFF\", corner_radius=0.12).set_fill(\"#FFFF00\")\n        # 5.5 s – 6.5 s: frame tween\n        self.play(Transform(frame, frame_to_2), run_time=1)\n        # 6.5 s – 7 s\n        self.wait(0.5)\n        under = Brace(frame, DOWN, buff=0.2, color=\"#58C4DD\")\n        under.set_z_index(2)\n        # 7 s – 7.5 s: under grow_from_center\n        self.play(GrowFromCenter(under), run_time=0.5)\n        # 7.5 s – 8.2 s\n        self.wait(0.7)\n        # 8.2 s – 9 s: frame fade_out, sum fade_out, under fade_out\n        self.play(FadeOut(frame), FadeOut(sum), FadeOut(under), run_time=0.8)\n",
    "gl": "# A box and a brace — exported by Manim Formula Editor for ManimGL 1.7.\n# Render at 1920×1080, 60 fps:\n#     manimgl ABoxAndABrace.py ABoxAndABrace -w -r 1920x1080 --fps 60\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 540 frames, like the editor's video export.\nfrom manimlib import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass ABoxAndABrace(Scene):\n    default_camera_config = dict(background_color=\"#000000\")\n\n    def construct(self):\n\n        # sum: 1+2+3+4+5+6\n        sum = Tex(r\"1+2+3+4+5+6\", font_size=61.868)\n        sum_g = _glyphs(sum, [\n            (-5.6902, 0.0474, 0.4342, 0.8763), (-4.5629, -0.0618, 0.875, 0.8763), (-3.43, 0.0474, 0.525, 0.8763), (-2.2968, -0.0618, 0.875, 0.8763),\n            (-1.164, 0.0329, 0.5461, 0.9053), (-0.0308, -0.0618, 0.875, 0.8763), (1.1021, 0.0546, 0.5829, 0.8908), (2.2353, -0.0618, 0.875, 0.8763),\n            (3.3682, 0.0329, 0.525, 0.9053), (4.5014, -0.0618, 0.875, 0.8763), (5.6343, 0.0329, 0.5461, 0.9053),\n        ])\n        sum.move_to([0, 0.6, 0])\n\n        # frame: box, built on sum where its clip starts\n\n        # under: brace, built on frame where its clip starts\n\n        # 0 s – 1.5 s: sum write\n        self.play(Write(VGroup(*sum_g[:]), stroke_color=\"#FFFFFF\"), run_time=1.5)\n        # 1.5 s – 2 s\n        self.wait(0.5)\n        frame = SurroundingRectangle(VGroup(*sum_g[:5]), buff=0.15, color=\"#FFFF00\").round_corners(0.12).set_fill(\"#FFFF00\")\n        frame_g = _glyphs(frame, [\n            (0, 0, 3.5029, 1),\n        ])\n        frame.set_z_index(1)\n        # 2 s – 2.6 s: frame create\n        self.play(ShowCreation(VGroup(frame_g[0])), run_time=0.6)\n        # 2.6 s – 3.5 s\n        self.wait(0.9)\n        frame_to = SurroundingRectangle(VGroup(*sum_g[6:]), buff=0.15, color=\"#83C167\", stroke_width=6, fill_opacity=0.25).round_corners(0.12).set_fill(\"#FFFF00\")\n        # 3.5 s – 4.5 s: frame tween\n        self.play(Transform(frame, frame_to), run_time=1)\n        # 4.5 s – 5.5 s\n        self.wait(1)\n        frame_to_2 = SurroundingRectangle(sum, buff=0.15, color=\"#FFFFFF\").round_corners(0.12).set_fill(\"#FFFF00\")\n        # 5.5 s – 6.5 s: frame tween\n        self.play(Transform(frame, frame_to_2), run_time=1)\n        # 6.5 s – 7 s\n        self.wait(0.5)\n        under = Brace(frame, DOWN, buff=0.2)\n        under.set_color(\"#58C4DD\")\n        under.set_z_index(2)\n        # 7 s – 7.5 s: under grow_from_center\n        self.play(GrowFromCenter(under), run_time=0.5)\n        # 7.5 s – 8.2 s\n        self.wait(0.7)\n        # 8.2 s – 9 s: frame fade_out, sum fade_out, under fade_out\n        self.play(FadeOut(frame), FadeOut(sum), FadeOut(under), run_time=0.8)\n"
  },
